<?php require 'config.php';role_required(['admin','teacher']);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cid=(int)$_POST['circle_id'];$f=$_FILES['file']??null;$allowed=['pdf','mp3','jpg','png'];$ext=strtolower(pathinfo($f['name']??'',PATHINFO_EXTENSION));if(!$f||$f['error']!==UPLOAD_ERR_OK||!in_array($ext,$allowed,true))$error='الملف غير صالح (PDF أو MP3 أو JPG أو PNG).';else{$dir=__DIR__.'/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(10)).'.'.$ext;if(move_uploaded_file($f['tmp_name'],$dir.'/'.$name)){$s=$pdo->prepare('INSERT INTO materials(circle_id,filename,filepath,uploaded_by) VALUES(?,?,?,?)');$s->execute([$cid,$f['name'],'uploads/'.$name,user()['id']]);$ok=true;}}}$circles=$pdo->query('SELECT id,title FROM circles ORDER BY title')->fetchAll();header_html('رفع مادة');if(!empty($ok))echo '<div class="alert success">تم رفع الملف.</div>';if($error)echo '<div class="alert error">'.e($error).'</div>';?><form method="post" enctype="multipart/form-data" class="card form"><label>الحلقة<select name="circle_id" required><?php foreach($circles as $c): ?><option value="<?=$c['id']?>"><?=e($c['title'])?></option><?php endforeach; ?></select></label><label>الملف<input type="file" name="file" required></label><input type="hidden" name="csrf" value="<?=csrf()?>"><button>رفع</button></form><?php footer_html(); ?>